"use client"

import * as React from "react"
import { AppWindowIcon, CommandIcon, KeyboardIcon } from "lucide-react"

import {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandSeparator,
  CommandShortcut,
} from "@tecton/react/components/command"
import { ShortcutKeys } from "@tecton/react/tecton/shortcuts"
import type { Shortcut } from "@tecton/react/tecton/shortcuts"

import {
  apps as defaultApps,
  commands as defaultCommands,
  groupApps,
} from "../data"
import type { ShellApp, ShellCommand } from "../data"

type ShellCommandPaletteProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  apps?: ShellApp[]
  /** Static host commands without a key binding. */
  commands?: ShellCommand[]
  /** Registered shortcuts (`useShortcuts()`), listed under their groups and runnable from here. */
  shortcuts?: Shortcut[]
  onSelectApp?: (app: ShellApp) => void
  onRunCommand?: (command: ShellCommand) => void
}

function groupBy<T>(items: T[], key: (item: T) => string) {
  const map = new Map<string, T[]>()
  for (const item of items) {
    const group = key(item)
    map.set(group, [...(map.get(group) ?? []), item])
  }
  return [...map.entries()]
}

/**
 * Shell command palette: switch application, run a registered shortcut or
 * a host command. Opened with ⌘K / Ctrl+K from anywhere in the shell.
 */
function ShellCommandPalette({
  open,
  onOpenChange,
  apps = defaultApps,
  commands = defaultCommands,
  shortcuts = [],
  onSelectApp,
  onRunCommand,
}: ShellCommandPaletteProps) {
  const shortcutGroups = React.useMemo(
    () =>
      groupBy(
        shortcuts.filter((shortcut) => !shortcut.hidden),
        (shortcut) => shortcut.group ?? "General"
      ),
    [shortcuts]
  )
  // A registered shortcut supersedes a static command with the same id,
  // label or keys, so an application binding a host command lists once.
  const commandGroups = React.useMemo(() => {
    const takenIds = new Set(shortcuts.map((shortcut) => shortcut.id))
    const takenLabels = new Set(
      shortcuts.map((shortcut) => shortcut.label.toLowerCase())
    )
    const takenKeys = new Set(
      shortcuts.map((shortcut) => shortcut.keys.toLowerCase())
    )
    return groupBy(
      commands.filter(
        (command) =>
          !takenIds.has(command.id) &&
          !takenLabels.has(command.label.toLowerCase()) &&
          !(command.shortcut && takenKeys.has(command.shortcut.toLowerCase()))
      ),
      (command) => command.group
    )
  }, [commands, shortcuts])

  const close = () => onOpenChange(false)

  return (
    <CommandDialog open={open} onOpenChange={onOpenChange}>
      <Command className="rounded-none bg-transparent">
        <CommandInput placeholder="Search apps and commands…" />
        <CommandList
          className="max-h-[60svh]"
          renderEmptyState={() => (
            <CommandEmpty>No results found.</CommandEmpty>
          )}
        >
          {groupApps(apps).map((group) => (
            <CommandGroup key={group.category} heading={group.category}>
              {group.apps.map((app) => (
                <CommandItem
                  key={app.id}
                  id={`app-${app.id}`}
                  textValue={`${app.code} ${app.name} ${app.category}`}
                  onAction={() => {
                    onSelectApp?.(app)
                    close()
                  }}
                >
                  <AppWindowIcon />
                  <span>{app.name}</span>
                  <span className="font-mono text-xs text-muted-foreground">
                    {app.code}
                  </span>
                </CommandItem>
              ))}
            </CommandGroup>
          ))}
          {shortcutGroups.map(([group, items]) => (
            <React.Fragment key={`shortcuts-${group}`}>
              <CommandSeparator />
              <CommandGroup heading={group}>
                {items.map((shortcut) => (
                  <CommandItem
                    key={shortcut.id}
                    id={`shortcut-${shortcut.id}`}
                    textValue={shortcut.label}
                    onAction={() => {
                      close()
                      shortcut.onAction(new KeyboardEvent("keydown"))
                    }}
                  >
                    <KeyboardIcon />
                    <span>{shortcut.label}</span>
                    <CommandShortcut>
                      <ShortcutKeys keys={shortcut.keys} />
                    </CommandShortcut>
                  </CommandItem>
                ))}
              </CommandGroup>
            </React.Fragment>
          ))}
          {commandGroups.map(([group, items]) => (
            <React.Fragment key={`commands-${group}`}>
              <CommandSeparator />
              <CommandGroup heading={group}>
                {items.map((command) => (
                  <CommandItem
                    key={command.id}
                    id={command.id}
                    textValue={command.label}
                    onAction={() => {
                      onRunCommand?.(command)
                      close()
                    }}
                  >
                    <CommandIcon />
                    <span>{command.label}</span>
                    {command.shortcut ? (
                      <CommandShortcut>{command.shortcut}</CommandShortcut>
                    ) : null}
                  </CommandItem>
                ))}
              </CommandGroup>
            </React.Fragment>
          ))}
        </CommandList>
      </Command>
    </CommandDialog>
  )
}

export { ShellCommandPalette }
export type { ShellCommandPaletteProps }

"use client"

import * as React from "react"
import { cn } from "cn"
import {
  BugIcon,
  CircleHelpIcon,
  HomeIcon,
  KeyboardIcon,
  LogOutIcon,
  SettingsIcon,
  SparklesIcon,
  UserIcon,
} from "lucide-react"

import { Button } from "@tecton/react/components/button"
import {
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
} from "@tecton/react/components/dropdown-menu"
import {
  AppFinder,
  AppFinderGroup,
  AppFinderInput,
  AppFinderItem,
  AppFinderList,
  AppFinderMenu,
  AppFinderTrigger,
} from "@tecton/react/tecton/app-finder"
import {
  AppShellAction,
  AppShellActions,
  AppShellCommandTrigger,
  AppShellDivider,
  AppShellHeader,
  AppShellNav,
  AppShellOverflow,
  AppShellUserMenu,
} from "@tecton/react/tecton/app-shell"
import {
  ShortcutsProvider,
  useShortcut,
  useShortcuts,
} from "@tecton/react/tecton/shortcuts"

import { ShellCommandPalette } from "./shell-command-palette"
import { ShellShortcutsDialog } from "./shell-shortcuts-dialog"
import {
  apps as defaultApps,
  appTones,
  currentUser,
  groupApps,
  recentAppIds as defaultRecentAppIds,
} from "../data"
import type { ShellApp, ShellUser } from "../data"

type ShellHeaderProps = Omit<
  React.ComponentProps<typeof AppShellHeader>,
  "children"
> & {
  apps?: ShellApp[]
  /** Id of the mounted application. */
  appId?: string
  onAppChange?: (app: ShellApp) => void
  user?: ShellUser
  /** Ids of recently used apps, listed first in the finder. */
  recentAppIds?: string[]
  /** Context shown after the home button: breadcrumb, workspace tabs, etc. */
  children?: React.ReactNode
}

/**
 * The host's top bar: app finder, home, application context and the
 * global action cluster. The mounted application only renders inside
 * `children` (its context) and the main region below.
 *
 * Responsive: the command trigger shrinks to an icon below `md`, and the
 * secondary actions (what's new, bug report, settings) fold into an
 * overflow menu below `lg`.
 *
 * Shortcuts: the header registers ⌘K / Ctrl+K (command palette) and `?`
 * (shortcut list) with the nearest `ShortcutsProvider`, creating one when
 * the host has none. Applications register theirs with `useShortcut` or
 * `registry.register`; both the palette and the `?` dialog list them.
 */
function ShellHeader(props: ShellHeaderProps) {
  return (
    <ShortcutsProvider>
      <ShellHeaderInner {...props} />
    </ShortcutsProvider>
  )
}

function ShellHeaderInner({
  className,
  apps = defaultApps,
  appId,
  onAppChange,
  user = currentUser,
  recentAppIds = defaultRecentAppIds,
  children,
  ...props
}: ShellHeaderProps) {
  const [internalAppId, setInternalAppId] = React.useState(apps[0]?.id)
  const currentId = appId ?? internalAppId
  const current = apps.find((app) => app.id === currentId) ?? apps[0]
  const [paletteOpen, setPaletteOpen] = React.useState(false)
  const [shortcutsOpen, setShortcutsOpen] = React.useState(false)
  const recent = recentAppIds
    .map((id) => apps.find((item) => item.id === id))
    .filter(
      (item): item is ShellApp => item !== undefined && item.id !== current?.id
    )
  const groups = groupApps(apps)
  const shortcuts = useShortcuts()

  const selectApp = (app: ShellApp) => {
    setInternalAppId(app.id)
    onAppChange?.(app)
  }

  useShortcut({
    id: "shell.palette",
    keys: "mod+k",
    label: "Search or jump to…",
    group: "Shell",
    onAction: () => setPaletteOpen((open) => !open),
  })
  useShortcut({
    id: "shell.shortcuts",
    keys: "?",
    label: "Keyboard shortcuts",
    group: "Shell",
    onAction: () => setShortcutsOpen((open) => !open),
  })

  // The shell always mounts an application; with an empty app list there is
  // nothing for the header to name.
  if (!current) return null

  const secondary = [
    { id: "whats-new", label: "What's new", icon: SparklesIcon },
    { id: "bug", label: "Report a bug", icon: BugIcon },
    { id: "settings", label: "Settings", icon: SettingsIcon },
  ]

  return (
    <AppShellHeader
      data-slot="shell-header"
      className={cn("gap-1 px-2 sm:gap-2", className)}
      {...props}
    >
      <AppFinder>
        <AppFinderTrigger name={current.name} tone={appTones[current.category]}>
          {current.code}
        </AppFinderTrigger>
        <AppFinderMenu>
          <AppFinderInput />
          <AppFinderList
            onAction={(key) => {
              const id = String(key).replace(/^recent-/, "")
              const app = apps.find((item) => item.id === id)
              if (app) selectApp(app)
            }}
          >
            {recent.length ? (
              <AppFinderGroup heading="Recent" hideWhileSearching>
                {recent.map((app) => (
                  <AppFinderItem
                    key={`recent-${app.id}`}
                    id={`recent-${app.id}`}
                    icon={app.code}
                    tone={appTones[app.category]}
                    name={app.name}
                    description={app.description}
                    keywords={[app.code, app.category]}
                  />
                ))}
              </AppFinderGroup>
            ) : null}
            {groups.map((group) => (
              <AppFinderGroup key={group.category} heading={group.category}>
                {group.apps.map((app) => (
                  <AppFinderItem
                    key={app.id}
                    id={app.id}
                    icon={app.code}
                    tone={appTones[app.category]}
                    name={app.name}
                    description={app.description}
                    keywords={[app.code, app.category]}
                    isCurrent={app.id === current.id}
                  />
                ))}
              </AppFinderGroup>
            ))}
          </AppFinderList>
        </AppFinderMenu>
      </AppFinder>
      <AppShellDivider className="hidden sm:block" />
      <Button
        variant="ghost"
        size="icon-sm"
        aria-label="Home"
        className="hidden sm:inline-flex"
      >
        <HomeIcon />
      </Button>
      <AppShellNav className="overflow-hidden">{children}</AppShellNav>
      <AppShellActions>
        <AppShellCommandTrigger onPress={() => setPaletteOpen(true)}>
          Search or jump to…
        </AppShellCommandTrigger>
        <AppShellAction
          label="Keyboard shortcuts"
          shortcut="?"
          onPress={() => setShortcutsOpen(true)}
        >
          <CircleHelpIcon />
        </AppShellAction>
        {secondary.map((action) => (
          <AppShellAction
            key={action.id}
            label={action.label}
            className="hidden lg:inline-flex"
          >
            <action.icon />
          </AppShellAction>
        ))}
        <AppShellOverflow className="lg:hidden">
          <DropdownMenuGroup>
            {secondary.map((action) => (
              <DropdownMenuItem key={action.id} textValue={action.label}>
                <action.icon /> {action.label}
              </DropdownMenuItem>
            ))}
          </DropdownMenuGroup>
        </AppShellOverflow>
        <AppShellUserMenu user={user}>
          <DropdownMenuGroup>
            <DropdownMenuLabel className="font-normal">
              <div className="grid leading-tight">
                <span className="truncate font-medium text-foreground">
                  {user.name}
                </span>
                <span className="truncate text-xs">{user.email}</span>
              </div>
            </DropdownMenuLabel>
          </DropdownMenuGroup>
          <DropdownMenuSeparator />
          <DropdownMenuGroup>
            <DropdownMenuItem textValue="Profile">
              <UserIcon /> Profile
            </DropdownMenuItem>
            <DropdownMenuItem textValue="Preferences">
              <SettingsIcon /> Preferences
            </DropdownMenuItem>
            <DropdownMenuItem
              textValue="Keyboard shortcuts"
              onAction={() => setShortcutsOpen(true)}
            >
              <KeyboardIcon /> Keyboard shortcuts
            </DropdownMenuItem>
          </DropdownMenuGroup>
          <DropdownMenuSeparator />
          <DropdownMenuGroup>
            <DropdownMenuItem textValue="Sign out">
              <LogOutIcon /> Sign out
            </DropdownMenuItem>
          </DropdownMenuGroup>
        </AppShellUserMenu>
      </AppShellActions>
      <ShellCommandPalette
        open={paletteOpen}
        onOpenChange={setPaletteOpen}
        apps={apps}
        shortcuts={shortcuts}
        onSelectApp={selectApp}
      />
      <ShellShortcutsDialog
        open={shortcutsOpen}
        onOpenChange={setShortcutsOpen}
        shortcuts={shortcuts}
      />
    </AppShellHeader>
  )
}

export { ShellHeader }
export type { ShellHeaderProps }

"use client"

import * as React from "react"

import {
  Dialog,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@tecton/react/components/dialog"
import {
  Empty,
  EmptyDescription,
  EmptyHeader,
  EmptyTitle,
} from "@tecton/react/components/empty"
import { ShortcutKeys } from "@tecton/react/tecton/shortcuts"
import type { Shortcut } from "@tecton/react/tecton/shortcuts"

type ShellShortcutsDialogProps = {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** The registered shortcuts, from `useShortcuts()`. */
  shortcuts: Shortcut[]
}

/** Groups the visible shortcuts by their `group`, in registration order. */
function groupShortcuts(shortcuts: Shortcut[]) {
  const groups = new Map<string, Shortcut[]>()
  for (const shortcut of shortcuts) {
    if (shortcut.hidden) continue
    const group = shortcut.group ?? "General"
    groups.set(group, [...(groups.get(group) ?? []), shortcut])
  }
  return [...groups.entries()]
}

/**
 * Keyboard shortcut reference for the shell: every shortcut registered by
 * the host and the mounted application, grouped. Opened with `?`.
 */
function ShellShortcutsDialog({
  open,
  onOpenChange,
  shortcuts,
}: ShellShortcutsDialogProps) {
  const groups = React.useMemo(() => groupShortcuts(shortcuts), [shortcuts])

  return (
    <Dialog isOpen={open} onOpenChange={onOpenChange} className="sm:max-w-lg">
      <DialogHeader>
        <DialogTitle>Keyboard shortcuts</DialogTitle>
        <DialogDescription>
          Shortcuts registered by the shell and by{" "}
          {groups.length > 1 ? "the current application" : "applications"}.
        </DialogDescription>
      </DialogHeader>
      {groups.length === 0 ? (
        <Empty className="py-8">
          <EmptyHeader>
            <EmptyTitle>No shortcuts</EmptyTitle>
            <EmptyDescription>
              The current application has not registered any.
            </EmptyDescription>
          </EmptyHeader>
        </Empty>
      ) : (
        <div className="grid gap-5 sm:grid-cols-2">
          {groups.map(([group, items]) => (
            <section key={group} className="flex flex-col gap-1">
              <h3 className="mb-1 text-xs font-medium text-muted-foreground">
                {group}
              </h3>
              {items.map((shortcut) => (
                <div
                  key={shortcut.id}
                  className="flex items-center justify-between gap-4 text-sm"
                >
                  <span className="truncate">{shortcut.label}</span>
                  <ShortcutKeys keys={shortcut.keys} className="shrink-0" />
                </div>
              ))}
            </section>
          ))}
        </div>
      )}
    </Dialog>
  )
}

export { ShellShortcutsDialog, groupShortcuts }
export type { ShellShortcutsDialogProps }
